async function dispatchEmergencyBroadcastClient(params) {
	const { request, candidateCloudDonorIds } = params;
	const fallbackId = request.id.replace(/[^a-zA-Z0-9_-]/g, "_").slice(0, 80) || `req_${Date.now()}`;
	if (!await ensureValidAuthSession()) return {
		requestId: fallbackId,
		syncedToCloud: false,
		alertsWritten: 0,
		pushChannelState: "NOT_CONFIGURED_BROWSER_REALTIME_ONLY",
		smsChannelState: "NOT_CONFIGURED",
		smsSentCount: 0,
		honestNotice: "Signed-out session: request saved locally on this device only. Sign in to broadcast to Neon PostgreSQL donors, or call opted-in donors directly."
	};
	const createdId = await createBloodRequestInFirestore(request);
	if (!createdId) return {
		requestId: fallbackId,
		syncedToCloud: false,
		alertsWritten: 0,
		pushChannelState: "NOT_CONFIGURED_BROWSER_REALTIME_ONLY",
		smsChannelState: "NOT_CONFIGURED",
		smsSentCount: 0,
		honestNotice: "Saved locally on this device. Use direct Call/WhatsApp on matched donors below."
	};
	let smsChannelState = "NOT_CONFIGURED";
	let smsSentCount = 0;
	let serverNote = "";
	try {
		const res = await apiFetch("/api/emergency/dispatch", {
			method: "POST",
			body: JSON.stringify({
				requestId: createdId,
				bloodGroup: request.bloodGroup,
				unitsNeeded: request.unitsNeeded,
				hospitalName: request.hospitalName,
				district: request.district,
				upazila: request.upazila,
				urgency: request.urgency,
				requiredTimeWindow: request.requiredTimeWindow || "IMMEDIATE_2H",
				escalationLevel: 0,
				searchRadiusKm: request.searchRadiusKm || 10,
				candidateDonorIds: candidateCloudDonorIds.slice(0, 25),
				optedInSmsPhones: []
			})
		});
		if (res.ok) {
			const data = await res.json().catch(() => ({}));
			smsChannelState = data?.channels?.smsStatus || "NOT_CONFIGURED";
			smsSentCount = Number(data?.channels?.smsSentCount) || 0;
			serverNote = String(data?.honestDeliveryNotice || "");
		}
	} catch {}
	return {
		requestId: createdId,
		syncedToCloud: true,
		alertsWritten: candidateCloudDonorIds.length,
		pushChannelState: "NOT_CONFIGURED_BROWSER_REALTIME_ONLY",
		smsChannelState,
		smsSentCount,
		honestNotice: serverNote || "Dispatched real-time Neon PostgreSQL alerts via WebSocket/SSE. Call opted-in donors directly in parallel for urgent cases."
	};
}
