async function adminSmartCleanupCompletedRequestsInFirestore() {
	const res = await apiFetch("/api/v1/requests?status=ALL&limit=50", { method: "GET" });
	if (!res.ok) return 0;
	const json = await res.json().catch(() => null);
	let cleaned = 0;
	for (const r of json?.items || []) if (r.status === "FULFILLED" || r.status === "CANCELLED") {
		if (await adminDeleteRequestInFirestore(String(r.id))) cleaned += 1;
	}
	return cleaned;
}
